// VULNERABLE: String concatenation allows SQL injection
public User login(String username, String password) {
    String sql = "SELECT * FROM users WHERE username = '" + username + 
                 "' AND password = '" + password + "'";

    try (var conn = dataSource.getConnection();
         var stmt = conn.createStatement();
         var rs = stmt.executeQuery(sql)) {

        if (rs.next()) {
            return new User(rs.getLong("id"), rs.getString("username"));
        }
    }
    return null;
}

// Attack scenario:
// username = "admin' OR '1'='1"
// password = "anything"
// Result SQL: SELECT * FROM users WHERE username = 'admin' OR '1'='1' AND password = 'anything'
// The OR '1'='1' makes the WHERE clause always true, bypassing authentication

// SAFE: PreparedStatement separates SQL structure from data
public User login(String username, String password) {
    String sql = "SELECT * FROM users WHERE username = ? AND password = ?";

    try (var conn = dataSource.getConnection();
         var pstmt = conn.prepareStatement(sql)) {

        // Phase 1: SQL template compiled by database with fixed structure
        pstmt.setString(1, username);  // Phase 2: bind username as data literal
        pstmt.setString(2, password);  // Phase 2: bind password as data literal

        try (var rs = pstmt.executeQuery()) {
            if (rs.next()) {
                return new User(rs.getLong("id"), rs.getString("username"));
            }
        }
    }
    return null;
}

// Attack scenario:
// username = "admin' OR '1'='1"
// Result: Database searches for a user whose username column literally equals "admin' OR '1'='1"
// The OR and quotes are just characters in the data, not SQL syntax

// Primary defense: PreparedStatement
// Secondary defense: Input validation before database layer
public List<Order> searchOrders(String orderStatus) {
    // Whitelist validation: only allow known order statuses
    var validStatuses = Set.of("PENDING", "SHIPPED", "DELIVERED", "CANCELLED");
    if (!validStatuses.contains(orderStatus.toUpperCase())) {
        throw new IllegalArgumentException("Invalid order status");
    }

    String sql = "SELECT * FROM orders WHERE status = ?";
    var orders = new ArrayList<Order>();

    try (var conn = dataSource.getConnection();
         var pstmt = conn.prepareStatement(sql)) {

        pstmt.setString(1, orderStatus);  // Still use PreparedStatement as primary defense

        try (var rs = pstmt.executeQuery()) {
            while (rs.next()) {
                orders.add(new Order(rs.getLong("id"), rs.getString("status")));
            }
        }
    }
    return orders;
}

// UNSAFE: String concatenation in JPQL
public List<User> findByUsernameUnsafe(String username) {
    String jpql = "SELECT u FROM User u WHERE u.username = '" + username + "'";
    return entityManager.createQuery(jpql, User.class).getResultList();
}

// SAFE: Named parameters in JPQL
public List<User> findByUsernameSafe(String username) {
    String jpql = "SELECT u FROM User u WHERE u.username = :username";
    return entityManager.createQuery(jpql, User.class)
                        .setParameter("username", username)  // Bound as data literal
                        .getResultList();
}

// SAFE: Spring Data JPA with @Query and named parameters
@Repository
public interface UserRepository extends JpaRepository<User, Long> {
    @Query("SELECT u FROM User u WHERE u.username = :username")
    List<User> findByUsername(@Param("username") String username);

    // ALSO SAFE: Derived query method (Spring generates safe query)
    List<User> findByUsernameAndStatus(String username, String status);
}

-- In PostgreSQL: Create a limited application user
-- As database admin, run these commands:

CREATE USER orderapp_user WITH PASSWORD 'secure_password';

-- Grant only necessary permissions on specific tables
GRANT CONNECT ON DATABASE orderdb TO orderapp_user;
GRANT USAGE ON SCHEMA public TO orderapp_user;

GRANT SELECT, INSERT, UPDATE, DELETE ON orders TO orderapp_user;
GRANT SELECT, INSERT, UPDATE, DELETE ON customers TO orderapp_user;
GRANT SELECT, INSERT, UPDATE, DELETE ON order_items TO orderapp_user;

-- Grant sequence usage for auto-increment IDs
GRANT USAGE, SELECT ON SEQUENCE orders_id_seq TO orderapp_user;
GRANT USAGE, SELECT ON SEQUENCE customers_id_seq TO orderapp_user;

