public List<Order> getOrdersSortedSafe(String sortColumn) {
    var allowedColumns = Map.of(
        "price", "price",
        "date", "order_date",
        "customer", "customer_name"
    );

    String validColumn = allowedColumns.get(sortColumn);
    if (validColumn == null) {
        throw new IllegalArgumentException("Invalid sort column");
    }

    // Safe to concatenate: validColumn is from whitelist, not user input
    String sql = "SELECT * FROM orders ORDER BY " + validColumn;

