-- In PostgreSQL: Create a stored procedure with parameterized input
-- SAFE: Parameters are treated as data literals by the database
CREATE OR REPLACE FUNCTION get_orders_by_status(
    p_status VARCHAR
)
RETURNS TABLE (
    order_id BIGINT,
    customer_name VARCHAR,
    order_date DATE,
    status VARCHAR
) AS $$
BEGIN
    -- Safe: p_status is a parameter, not concatenated into SQL string
    RETURN QUERY
    SELECT id, customer_name, order_date, status
    FROM orders
    WHERE status = p_status;  -- Parameter used safely
END;
$$ LANGUAGE plpgsql;

// In Spring Boot JDBC: Call stored procedure safely
public List<Order> getOrdersByStatus(String status) {
    String sql = "{call get_orders_by_status(?)}";
    var orders = new ArrayList<Order>();

    try (var conn = dataSource.getConnection();
         var cstmt = conn.prepareCall(sql)) {

        cstmt.setString(1, status);  // Bind parameter to stored procedure
        try (var rs = cstmt.executeQuery()) {
            while (rs.next()) {
                orders.add(new Order(
                    rs.getLong("order_id"),
                    rs.getString("status")
                ));
            }
        }
    }
    return orders;
}
